ext('c12_chem_ch1',[
C("🥤","विलयन में प्रतिशत और ppm",["द्रव्यमान प्रतिशत","आयतन प्रतिशत","ppm: बहुत कम सांद्रता","प्रदूषण मापने में उपयोगी"],"विलयन की सांद्रता को कई तरह से बताया जाता है। द्रव्यमान प्रतिशत बताता है कि सौ ग्राम विलयन में कितना ग्राम विलेय है। आयतन प्रतिशत द्रवों के मिश्रण में काम आता है। जब विलेय बहुत थोड़ा हो, जैसे पानी में प्रदूषक, तो पीपीएम में बताते हैं, यानी दस लाख भाग में कितने भाग।"),
C("🌡️","ताप का घुलनशीलता पर प्रभाव",["ठोस की घुलनशीलता प्रायः बढ़ती","गैस की घुलनशीलता घटती","गर्म पानी में ऑक्सीजन कम","जलीय जीवों पर असर"],"ज़्यादातर ठोस पदार्थों की घुलनशीलता ताप बढ़ने पर बढ़ती है, इसी कारण गर्म चाय में चीनी जल्दी घुलती है। लेकिन गैसों की घुलनशीलता ताप बढ़ने पर घटती है। इसलिए गर्म पानी में घुली ऑक्सीजन कम हो जाती है, जिससे मछलियों जैसे जलीय जीवों को परेशानी हो सकती है।"),
C("🧊","हिमांक का अवनमन",["विलेय मिलाने पर हिमांक घटता","समुद्र का पानी देर से जमता","सड़क पर नमक डालना","ठंड में गाड़ी में एंटीफ्रीज़"],"किसी शुद्ध विलायक में अवाष्पशील विलेय मिलाने पर उसका हिमांक घट जाता है। यही कारण है कि समुद्र का खारा पानी साफ़ पानी से कम तापमान पर जमता है। बर्फ़ीली सड़कों पर नमक डाला जाता है ताकि बर्फ़ पिघल जाए। ठंडे देशों में गाड़ियों के इंजन में एंटीफ्रीज़ डालने का कारण भी यही है।"),
C("🌡️","क्वथनांक का उन्नयन",["विलेय मिलाने पर क्वथनांक बढ़ता","वाष्प दाब घटने से","अवाष्पशील विलेय के साथ","मोलल उन्नयन स्थिरांक"],"अवाष्पशील विलेय मिलाने पर विलयन का वाष्प दाब घट जाता है, इसलिए उसे उबालने के लिए ज़्यादा ताप चाहिए। यह क्वथनांक का उन्नयन है। नमक वाले पानी का क्वथनांक शुद्ध पानी से थोड़ा ज़्यादा होता है। यह बदलाव विलयन की मोललता के अनुपात में होता है।"),
C("🧪","आदर्श और अनादर्श विलयन",["आदर्श: राउल्ट के नियम का पालन","अनादर्श: धनात्मक या ऋणात्मक विचलन","धनात्मक विचलन में वाष्प दाब ज़्यादा","ऋणात्मक विचलन में वाष्प दाब कम"],"जो विलयन हर सांद्रता पर राउल्ट के नियम का पालन करते हैं, वे आदर्श विलयन कहलाते हैं। इनमें अणुओं के बीच आकर्षण बल लगभग समान होते हैं। जो इसका पालन नहीं करते, वे अनादर्श हैं। धनात्मक विचलन में वाष्प दाब अपेक्षा से ज़्यादा होता है, और ऋणात्मक विचलन में कम।"),
C("🧮","एक हल किया उदाहरण: मोलरता",["चार ग्राम सोडियम हाइड्रॉक्साइड","एक लीटर विलयन","मोलर द्रव्यमान चालीस","मोलरता शून्य दशमलव एक"],"मान लीजिए चार ग्राम सोडियम हाइड्रॉक्साइड एक लीटर विलयन में घुला है। इसका मोलर द्रव्यमान चालीस ग्राम प्रति मोल है। इसलिए मोलों की संख्या चार भाग चालीस, यानी शून्य दशमलव एक है। एक लीटर में शून्य दशमलव एक मोल होने का मतलब है कि विलयन की मोलरता शून्य दशमलव एक मोलर है।"),
],5)
ext('c12_chem_ch2',[
C("🔋","सेल का प्रदर्शन: एक उदाहरण",["जस्ता का ऑक्सीकरण","तांबे पर अपचयन","इलेक्ट्रॉन तार से बहते","लवण सेतु आवेश संतुलित करता"],"डेनियल सेल में जस्ता की छड़ ऑक्सीकृत होकर जिंक आयन बनाती है और इलेक्ट्रॉन छोड़ती है। ये इलेक्ट्रॉन बाहरी तार से तांबे की छड़ तक पहुँचते हैं, जहाँ कॉपर आयन अपचयित होकर तांबा बनते हैं। लवण सेतु दोनों विलयनों में आयन भेजकर आवेश को संतुलित रखता है। इसी से विद्युत धारा बनती है।"),
C("⚡","सेल का विभव और स्पर्शिता",["विद्युत वाहक बल","अवयवों के विभव का अंतर","मानक स्थितियों में","वोल्ट में मापा जाता है"],"सेल का विभव कैथोड और एनोड के इलेक्ट्रोड विभवों के अंतर के बराबर होता है। मानक स्थितियों में यह मान मानक सेल विभव कहलाता है। अगर यह मान धनात्मक हो, तो अभिक्रिया अपने आप होती है और वह सेल उपयोगी विद्युत धारा दे सकता है। इसे वोल्टमीटर से मापा जाता है।"),
C("💧","चालकता का सांद्रता से संबंध",["सांद्रता घटे तो चालकता घटती","मोलर चालकता बढ़ती","प्रबल विद्युत अपघट्य","दुर्बल विद्युत अपघट्य"],"विलयन में जितने ज़्यादा आयन होंगे, चालकता उतनी ज़्यादा होगी। विलयन को तनु करने पर चालकता घटती है क्योंकि आयन कम हो जाते हैं। लेकिन मोलर चालकता बढ़ती है। प्रबल विद्युत अपघट्य में यह वृद्धि कम होती है, जबकि दुर्बल विद्युत अपघट्य में तनुता पर यह तेज़ी से बढ़ती है।"),
C("🏭","विद्युत अपघटन के उपयोग",["सोडियम और क्लोरीन का निष्कर्षण","इलेक्ट्रोप्लेटिंग","धातु का शोधन","एल्युमिनियम का उत्पादन"],"विद्युत अपघटन कई उद्योगों में काम आता है। इससे गलित सोडियम क्लोराइड से सोडियम और क्लोरीन बनते हैं। इलेक्ट्रोप्लेटिंग में किसी वस्तु पर चाँदी या क्रोमियम की पतली परत चढ़ाई जाती है। इससे अशुद्ध धातु का शोधन भी किया जाता है और एल्युमिनियम जैसी धातु का निष्कर्षण भी होता है।"),
C("🪫","प्राथमिक और द्वितीयक बैटरी",["प्राथमिक: एक बार उपयोग","द्वितीयक: पुनः आवेशित","लेड संचायक बैटरी","लिथियम आयन बैटरी"],"प्राथमिक बैटरी में अभिक्रिया उलटी नहीं हो सकती, इसलिए उसे एक बार ही काम में लाते हैं। टॉर्च का सूखा सेल इसका उदाहरण है। द्वितीयक बैटरी को दोबारा आवेशित किया जा सकता है। गाड़ी की लेड संचायक बैटरी और मोबाइल की लिथियम आयन बैटरी इसके उदाहरण हैं।"),
C("🌿","ईंधन सेल",["हाइड्रोजन और ऑक्सीजन","सीधे विद्युत ऊर्जा","जल उत्पाद के रूप में","प्रदूषण कम"],"ईंधन सेल में हाइड्रोजन और ऑक्सीजन की अभिक्रिया से सीधे विद्युत ऊर्जा बनती है, बिना ईंधन को जलाए। इसका एकमात्र उत्पाद जल है, इसलिए यह बहुत कम प्रदूषण करता है। अंतरिक्ष यानों में इसका उपयोग हुआ है। इसकी दक्षता भी साधारण ताप इंजनों से अधिक होती है।"),
],5)
ext('c12_chem_ch3',[
C("⏲️","अर्ध-आयु का अर्थ",["अभिकारक आधा होने का समय","प्रथम कोटि में स्थिर","शून्य कोटि में सांद्रता पर निर्भर","रेडियोधर्मी क्षय में उपयोग"],"अर्ध-आयु वह समय है जिसमें अभिकारक की सांद्रता घटकर आधी हो जाती है। प्रथम कोटि की अभिक्रिया में अर्ध-आयु प्रारंभिक सांद्रता पर निर्भर नहीं करती, वह एक स्थिर मान होती है। इसी कारण रेडियोधर्मी पदार्थों के क्षय की गणना में अर्ध-आयु बहुत काम आती है।"),
C("🧮","प्रथम कोटि का हल किया उदाहरण",["वेग स्थिरांक दिया","प्रारंभिक सांद्रता दी","समय के बाद शेष सांद्रता","लघुगणक का उपयोग"],"मान लीजिए एक प्रथम कोटि की अभिक्रिया का वेग स्थिरांक ज्ञात है और प्रारंभिक सांद्रता भी। तब समय बीतने के बाद सांद्रता प्रथम कोटि के समाकलित सूत्र से निकाली जाती है। इसमें लघुगणक का उपयोग होता है। अर्ध-आयु के लिए शून्य दशमलव छह नौ तीन को वेग स्थिरांक से भाग देते हैं।"),
C("🎢","सक्रियण ऊर्जा",["अभिक्रिया के लिए ऊर्जा बाधा","न्यूनतम ऊर्जा चाहिए","ऊँची बाधा: धीमी अभिक्रिया","उत्प्रेरक बाधा घटाता है"],"हर अभिक्रिया के लिए अभिकारी अणुओं को एक न्यूनतम ऊर्जा चाहिए, जिसे सक्रियण ऊर्जा कहते हैं। इसे एक पहाड़ की चढ़ाई की तरह समझ सकते हैं। जितनी ऊँची बाधा, उतनी धीमी अभिक्रिया। उत्प्रेरक इस बाधा को घटा देता है, इसलिए वही अभिक्रिया कम ताप पर भी तेज़ी से होती है।"),
C("📈","आरहेनियस समीकरण",["वेग स्थिरांक और ताप का संबंध","सक्रियण ऊर्जा का प्रभाव","ताप बढ़ने पर वृद्धि","दस डिग्री पर लगभग दुगुनी"],"आरहेनियस समीकरण वेग स्थिरांक, ताप और सक्रियण ऊर्जा को जोड़ता है। इससे पता चलता है कि ताप बढ़ाने पर वेग स्थिरांक तेज़ी से बढ़ता है। प्रायः ताप दस डिग्री बढ़ने पर अभिक्रिया का वेग लगभग दुगुना हो जाता है। सक्रियण ऊर्जा जितनी कम हो, वेग उतना ज़्यादा होता है।"),
C("🧪","अभिक्रिया की कोटि कैसे पता करें",["प्रयोग से सांद्रता और वेग","एक सांद्रता बदलकर देखें","वेग कितना बदला","कोटि का निर्धारण"],"अभिक्रिया की कोटि प्रयोग से ही पता चलती है, रासायनिक समीकरण देखकर नहीं। एक अभिकारक की सांद्रता बदलकर और बाकी स्थिर रखकर वेग मापा जाता है। अगर सांद्रता दुगुनी करने पर वेग भी दुगुना हो, तो वह कोटि एक है। अगर वेग चार गुना हो, तो वह कोटि दो है।"),
C("🍽️","दैनिक जीवन में बलगतिकी",["खाना पकाने का समय","भोजन का खराब होना","रेफ्रिजरेटर में ताप घटाना","प्रेशर कुकर में दाब बढ़ाना"],"दैनिक जीवन में बलगतिकी के नियम काम आते हैं। प्रेशर कुकर में पानी का क्वथनांक बढ़ जाता है, इसलिए दाल जल्दी पक जाती है। रेफ्रिजरेटर में भोजन को ठंडा रखकर उसके खराब होने की अभिक्रिया धीमी की जाती है। यानी ताप बदलकर हम अभिक्रियाओं की गति को अपने काम के लिए नियंत्रित करते हैं।"),
],5)
ext('c12_chem_ch4',[
C("🎨","संक्रमण यौगिकों का रंग",["अधूरी भरी d कक्षक","इलेक्ट्रॉन ऊर्जा सोखकर कूदता","शेष प्रकाश का रंग दिखता","तांबे के लवण नीले"],"संक्रमण तत्वों के आयनों में डी कक्षक अधूरे भरे होते हैं। प्रकाश पड़ने पर इलेक्ट्रॉन कुछ ऊर्जा सोखकर ऊपर के कक्षक में चला जाता है। बाकी बचा प्रकाश आँखों तक पहुँचता है, इसलिए यौगिक रंगीन दिखता है। कॉपर सल्फेट का नीला रंग इसी कारण है।"),
C("🧲","चुंबकीय गुण",["अयुग्मित इलेक्ट्रॉन","अनुचुंबकीय गुण","जितने अयुग्मित, उतना चुंबकत्व","मानक चुंबकीय आघूर्ण"],"जिन आयनों में अयुग्मित इलेक्ट्रॉन होते हैं, वे अनुचुंबकीय होते हैं और चुंबक की ओर खिंचते हैं। अयुग्मित इलेक्ट्रॉन जितने ज़्यादा होते हैं, चुंबकीय गुण उतना ही ज़्यादा होता है। इसे बोर मैग्नेटॉन इकाई में मापते हैं। सभी इलेक्ट्रॉन युग्मित हों, तो पदार्थ प्रतिचुंबकीय होता है।"),
C("🟣","पोटैशियम परमैंगनेट की अभिक्रियाएँ",["अम्लीय माध्यम में प्रबल ऑक्सीकारक","फेरस को फेरिक में","ऑक्सालिक अम्ल का ऑक्सीकरण","रंग बैंगनी से रंगहीन"],"पोटैशियम परमैंगनेट अम्लीय माध्यम में बहुत प्रबल ऑक्सीकारक है। यह फेरस आयन को फेरिक आयन में बदल देता है। यह ऑक्सालिक अम्ल को भी ऑक्सीकृत कर देता है। इन अभिक्रियाओं में इसका गहरा बैंगनी रंग गायब हो जाता है, इसलिए अनुमापन में किसी अलग सूचक की ज़रूरत नहीं पड़ती।"),
C("🟠","डाइक्रोमेट और क्रोमेट का संतुलन",["pH बदलने पर रंग बदलता","अम्ल में नारंगी डाइक्रोमेट","क्षार में पीला क्रोमेट","उलटने योग्य अभिक्रिया"],"क्रोमेट और डाइक्रोमेट आयन विलयन के माध्यम के अनुसार एक-दूसरे में बदलते रहते हैं। अम्लीय माध्यम में नारंगी रंग का डाइक्रोमेट बनता है। क्षारीय माध्यम में पीला क्रोमेट बनता है। यह अभिक्रिया उलटने योग्य है, इसलिए माध्यम बदलने पर रंग भी वापस बदल जाता है।"),
C("☢️","ऐक्टिनॉयड तत्वों की विशेषताएँ",["सभी रेडियोधर्मी","कई ऑक्सीकरण अवस्थाएँ","यूरेनियम और थोरियम प्रमुख","परमाणु ऊर्जा में उपयोग"],"ऐक्टिनॉयड श्रेणी के सभी तत्व रेडियोधर्मी होते हैं। लैन्थेनॉयड की तुलना में इनमें कई ऑक्सीकरण अवस्थाएँ पाई जाती हैं। यूरेनियम और थोरियम इनके प्रमुख उदाहरण हैं। इनका उपयोग परमाणु ऊर्जा और परमाणु ईंधन में होता है, इसलिए ये ऊर्जा क्षेत्र में महत्त्वपूर्ण हैं।"),
C("🛠️","संक्रमण धातुओं के उपयोग",["लोहा: निर्माण और इस्पात","तांबा: तार और बर्तन","टाइटेनियम: विमान के पुर्ज़े","उत्प्रेरक के रूप में"],"संक्रमण धातुएँ हमारे जीवन में बहुत काम आती हैं। लोहे से इस्पात बनाकर इमारतें और पुल बनाए जाते हैं। तांबे का उपयोग बिजली के तार और बर्तनों में होता है। टाइटेनियम हल्का और मज़बूत होने से विमानों में काम आता है। कई संक्रमण धातुएँ उद्योग में उत्प्रेरक भी बनती हैं।"),
],5)
ext('c12_chem_ch5',[
C("🔗","समन्वय संख्या का उदाहरण",["केंद्रीय परमाणु से जुड़ी लिगन्ड संख्या","हेक्साऐम्मीन कोबाल्ट: छह","टेट्राऐम्मीन ज़िंक: चार","संख्या से आकृति का अनुमान"],"समन्वय संख्या वह संख्या है जो बताती है कि केंद्रीय धातु आयन से कितने लिगन्ड सीधे जुड़े हैं। उदाहरण के लिए, हेक्साऐम्मीन कोबाल्ट में समन्वय संख्या छह है, और टेट्राऐम्मीन ज़िंक में चार। यह संख्या यौगिक की आकृति तय करने में मदद करती है, जैसे छह पर अष्टफलकीय और चार पर चतुष्फलकीय।"),
C("🔤","नामकरण का एक पूरा उदाहरण",["पहले धनायन, फिर ऋणायन","लिगन्ड वर्णमाला क्रम में","धातु के बाद ऑक्सीकरण अवस्था","ऋणायनी संकुल में धातु का एट"],"उपसहसंयोजन यौगिक के नामकरण में पहले धनायन और फिर ऋणायन का नाम लिखा जाता है। संकुल के भीतर लिगन्ड वर्णमाला के क्रम में पहले आते हैं और धातु बाद में, उसके बाद रोमन अंकों में ऑक्सीकरण अवस्था। अगर संकुल स्वयं ऋणायन हो, तो धातु के नाम के अंत में एट लगाया जाता है।"),
C("🪞","ज्यामितीय समावयवता",["सिस और ट्रांस रूप","एक ही तल में पास या दूर","वर्गाकार समतलीय में संभव","अष्टफलकीय में भी संभव"],"जब वही लिगन्ड धातु के चारों ओर अलग-अलग स्थानों पर जुड़ते हैं, तो ज्यामितीय समावयवता होती है। सिस रूप में समान लिगन्ड एक-दूसरे के पास होते हैं, और ट्रांस रूप में सामने की ओर। यह समावयवता वर्ग समतलीय और अष्टफलकीय दोनों तरह के संकुलों में मिल सकती है।"),
C("🌈","क्रिस्टल क्षेत्र सिद्धांत और रंग",["लिगन्ड d कक्षकों को विभाजित करते","ऊर्जा अंतर के अनुसार रंग","प्रबल क्षेत्र वाले लिगन्ड","दुर्बल क्षेत्र वाले लिगन्ड"],"क्रिस्टल क्षेत्र सिद्धांत में लिगन्ड को ऋणावेशित बिंदु मानकर चलते हैं। इनके प्रभाव से धातु के डी कक्षक दो समूहों में बँट जाते हैं। इन समूहों के बीच ऊर्जा अंतर के अनुसार संकुल अलग-अलग रंग का प्रकाश सोखता है। प्रबल क्षेत्र वाले लिगन्ड ऊर्जा अंतर अधिक बनाते हैं।"),
C("🩸","जैव प्रणालियों में संकुल",["हीमोग्लोबिन में आयरन","क्लोरोफ़िल में मैग्नीशियम","विटामिन बारह में कोबाल्ट","शरीर के लिए अनिवार्य"],"उपसहसंयोजन यौगिक जीवन के लिए भी आवश्यक हैं। हीमोग्लोबिन में आयरन का संकुल ऑक्सीजन ले जाता है। क्लोरोफ़िल में मैग्नीशियम का संकुल प्रकाश संश्लेषण में सहायता करता है। विटामिन बारह में कोबाल्ट का संकुल है। इनके बिना जीवन की ये मूल क्रियाएँ संभव नहीं।"),
C("🏭","उद्योग और चिकित्सा में उपयोग",["सोने और चाँदी का निष्कर्षण","इलेक्ट्रोप्लेटिंग","सिस प्लैटिन कैंसर चिकित्सा में","जल की कठोरता हटाने में"],"संकुल यौगिकों का उपयोग उद्योग में भी होता है। साइनाइड संकुल बनाकर सोने और चाँदी का निष्कर्षण किया जाता है। इलेक्ट्रोप्लेटिंग में भी इनका प्रयोग होता है। चिकित्सा में सिस प्लैटिन नाम का संकुल कैंसर के इलाज में काम आता है। कठोर जल को मृदु बनाने में भी ये उपयोगी हैं।"),
],5)
